import React, {
  forwardRef,
  PropsWithChildren,
  ReactElement,
  useImperativeHandle,
  useRef,
} from 'react';

import { MeterBarChartOverlay } from './components/MeterBarChartOverlay/MeterBarChartOverlay.js';
import { MeterBarChartPlot } from './components/MeterBarChartPlot/MeterBarChartPlot.js';
import { MeterBarChartSegment } from './components/MeterBarChartSegment/MeterBarChartSegment.js';
import { MeterBarChartThresholdLegend } from './components/MeterBarChartThresholdLegend/MeterBarChartThresholdLegend.js';
import { MeterBarThresholdIndicator } from './components/MeterBarThresholdIndicator.js';
import { MeterBarChartDataProvider } from './context/MeterBarChartDataContext.js';
import { buildThresholds } from './functions/build-thresholds.js';
import { useMeterBarChartConfig } from './hooks/useMeterBarChartConfig.js';
import { StoreProvider } from './providers/StoreProvider.js';
import { Icon } from './slots/Icon.js';
import { Label } from './slots/Label.js';
import { Max } from './slots/Max.js';
import { Min } from './slots/Min.js';
import { Threshold } from './slots/Threshold.js';
import { ThresholdLegend } from './slots/ThresholdLegend.js';
import { Thresholds } from './slots/Thresholds.js';
import { Tooltip } from './slots/Tooltip.js';
import { Value } from './slots/Value.js';
import { SEGMENT_COLOR_DEFAULT, NAME_DEFAULT_VALUE } from './types/default.js';
import { type MeterBarChartConsumerConfig } from './types/meter-bar-chart-config.js';
import { type MeterBarChartInternalConfig } from './types/meter-bar-chart-internal.js';
import {
  type MeterBarChartRef,
  type MeterBarChartProps,
} from './types/meter-bar-chart.js';
import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import { useObserveContainerSize } from '../../core/components/chart-layout/hooks/useObserveContainerSize.js';
import { LegendSizeContext } from '../../core/components/legend/shared/context/LegendSizeContext.js';
import { ChartType } from '../../core/types/chart-types.js';
import { MeterBarChartFormattedValue } from '../shared/components/formatted-value/MeterBarChartFormattedValue.js';
import { MeterBarLayout } from '../shared/components/meter-bar-layout/MeterBarLayout.js';
import { FormatterContext } from '../shared/context/FormatterContext.js';
import { getLabelValue } from '../shared/functions/get-label-value.js';
import { LEGEND_VERTICAL_RATIO } from '../shared/types/default.js';

/**
 * Single meter bar chart component
 * TODO try to split in subcomponents
 */
const _MeterBarChart = forwardRef<
  HTMLDivElement,
  PropsWithChildren<MeterBarChartProps>
>((props, forwardedRef) => {
  const {
    value,
    color = SEGMENT_COLOR_DEFAULT,
    name = NAME_DEFAULT_VALUE,
    className,
    style,
  } = props;

  const config: MeterBarChartInternalConfig = useMeterBarChartConfig(props);
  const {
    size,
    thresholds,
    min,
    max,
    minSlot,
    maxSlot,
    iconSlot,
    valueSlot,
    labelSlot,
    tooltip,
    formatter,
  } = config;

  const meterBarChartRef = useRef<MeterBarChartRef>(null);

  useImperativeHandle(forwardedRef, () => {
    if (meterBarChartRef.current) {
      const consumerConfig: MeterBarChartConsumerConfig = {
        thresholds,
        size,
        min,
        max,
        formatter,
        tooltip,
      };
      meterBarChartRef.current.getConfig = () =>
        JSON.stringify({ type: ChartType.SingleMeterBar, ...consumerConfig });
    }
    // We are ignoring this eslint rule as this will always be defined since we are relying on the consumer to pass the reference value.
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion,newline-before-return
    return meterBarChartRef.current!;
  });

  const [{ width, wrapperHeight }, containerRef] = useObserveContainerSize();
  const ref = useMergeRefs([forwardedRef, containerRef, meterBarChartRef]);

  const { matchingThreshold, thresholdIndicators, legendItems } =
    buildThresholds(value, min, max, width, thresholds);

  const meterBarChartData = {
    color: matchingThreshold?.color ?? color,
    max,
    min,
    name,
    value,
    width,
    label: labelSlot ? getLabelValue(labelSlot as ReactElement) : '',
    tooltip,
  };

  return (
    <FormatterContext.Provider value={{ formatter }}>
      <MeterBarChartDataProvider data={meterBarChartData}>
        <MeterBarLayout
          ref={ref}
          size={size}
          className={className}
          style={style}
        >
          {iconSlot && <MeterBarLayout.Icon>{iconSlot}</MeterBarLayout.Icon>}
          {labelSlot && (
            <MeterBarLayout.Label>{labelSlot}</MeterBarLayout.Label>
          )}
          {valueSlot && (
            <MeterBarLayout.Value>
              <MeterBarChartFormattedValue
                value={value}
                total={max - min}
                auto={valueSlot?.auto}
              >
                {valueSlot?.value}
              </MeterBarChartFormattedValue>
            </MeterBarLayout.Value>
          )}
          <MeterBarLayout.Chart>
            <StoreProvider>
              <MeterBarChartOverlay>
                <MeterBarChartPlot>
                  <MeterBarChartSegment />
                  {thresholdIndicators.map((thresholdIndicator) => (
                    <MeterBarThresholdIndicator
                      key={`indicator-${thresholdIndicator}`}
                      position={thresholdIndicator}
                    />
                  ))}
                </MeterBarChartPlot>
              </MeterBarChartOverlay>
            </StoreProvider>
          </MeterBarLayout.Chart>
          {minSlot && (
            <MeterBarLayout.Min>
              <MeterBarChartFormattedValue value={min} auto={minSlot?.auto}>
                {minSlot?.value}
              </MeterBarChartFormattedValue>
            </MeterBarLayout.Min>
          )}
          {maxSlot && (
            <MeterBarLayout.Max>
              <MeterBarChartFormattedValue value={max} auto={maxSlot?.auto}>
                {maxSlot?.value}
              </MeterBarChartFormattedValue>
            </MeterBarLayout.Max>
          )}
          {thresholds?.legend && legendItems.length > 0 && (
            <MeterBarLayout.Legend>
              <LegendSizeContext.Provider
                value={{ width, height: wrapperHeight * LEGEND_VERTICAL_RATIO }}
              >
                <MeterBarChartThresholdLegend data={legendItems} />
              </LegendSizeContext.Provider>
            </MeterBarLayout.Legend>
          )}
        </MeterBarLayout>
      </MeterBarChartDataProvider>
    </FormatterContext.Provider>
  );
});

_MeterBarChart['displayName'] = 'MeterBarChart';

/**
 * The `MeterBarChart` provides a lightweight and simple visualization progress
 * toward a completion, consumption of a total, etc.  It consists of a horizontal
 * bar that gradually fills up with color or shading as it approaches the max value.
 */
export const MeterBarChart = Object.assign(_MeterBarChart, {
  Value,
  Label,
  Icon,
  Min,
  Max,
  Thresholds,
  Threshold,
  ThresholdLegend,
  Tooltip,
});
